css:
.sigserv-container {
    padding: 22px;
    background: radial-gradient(1200px 600px at 80% -10%, rgba(255, 87, 156, 0.12), transparent 60%),
                linear-gradient(160deg, #0a0814 0%, #150f2b 45%, #0d1424 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #d8d8ec;
}

.sigserv-container .sigserv-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 18px;
    background: linear-gradient(120deg, #2a1148 0%, #3d1a5c 50%, #6a1f55 100%);
    padding: 26px 30px;
    border-radius: 18px;
    margin-bottom: 22px;
    box-shadow: 0 10px 40px rgba(255, 87, 156, 0.18);
    border: 1px solid rgba(255, 178, 102, 0.18);
    flex-wrap: wrap;
}

.sigserv-container .sigserv-header-text h1 {
    font-size: 1.9rem;
    font-weight: 800;
    margin: 0 0 6px 0;
    color: #ffffff;
    letter-spacing: -0.4px;
    background: linear-gradient(90deg, #ffd28a, #ff5f9c);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

.sigserv-container .sigserv-header-text p {
    margin: 0;
    font-size: 0.92rem;
    color: #e6cfe6;
    opacity: 0.92;
}

.sigserv-container .sigserv-cap-chip {
    background: rgba(0, 0, 0, 0.34);
    border: 1px solid rgba(255, 178, 102, 0.35);
    border-radius: 14px;
    padding: 12px 20px;
    text-align: center;
    min-width: 180px;
}

.sigserv-container .sigserv-cap-label {
    display: block;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #f6b86b;
    margin-bottom: 4px;
}

.sigserv-container .sigserv-cap-value {
    display: block;
    font-size: 1.5rem;
    font-weight: 800;
    color: #ffe2b0;
}

.sigserv-container .sigserv-period-counter {
    text-align: center;
    font-size: 1.05rem;
    margin-bottom: 18px;
    color: #9d9dc4;
    letter-spacing: 0.5px;
}

.sigserv-container .sigserv-period-counter span { margin: 0 3px; }
.sigserv-container .sigserv-period-counter #currentDay,
.sigserv-container .sigserv-period-counter #maxPeriods {
    font-weight: 800;
    color: #ff5f9c;
}

.sigserv-container .sigserv-briefing {
    background: linear-gradient(135deg, rgba(26, 16, 46, 0.9) 0%, rgba(14, 20, 36, 0.9) 100%);
    border-left: 4px solid #ff5f9c;
    border-radius: 12px;
    padding: 20px 24px;
    margin-bottom: 22px;
}

.sigserv-container .sigserv-briefing-badge {
    display: inline-block;
    background: linear-gradient(90deg, #ff5f9c, #ff9d5c);
    color: #1a0a14;
    font-size: 0.68rem;
    font-weight: 800;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 20px;
    margin-bottom: 10px;
    letter-spacing: 0.8px;
}

.sigserv-container .sigserv-briefing h3 {
    color: #ffffff;
    font-size: 1.18rem;
    margin: 0 0 8px 0;
}

.sigserv-container .sigserv-briefing p {
    color: #b9b9d6;
    font-size: 0.93rem;
    line-height: 1.65;
    margin: 0;
}

.sigserv-container .sigserv-kpis {
    display: grid;
    grid-template-columns: 1.4fr 1fr 1fr 1fr 1fr;
    gap: 14px;
    margin-bottom: 22px;
}

.sigserv-container .sigserv-kpi {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 14px;
    padding: 16px 14px;
    text-align: center;
    backdrop-filter: blur(8px);
    transition: transform 0.25s ease, border-color 0.25s ease;
}

.sigserv-container .sigserv-kpi:hover {
    transform: translateY(-3px);
    border-color: rgba(255, 95, 156, 0.4);
}

.sigserv-container .sigserv-kpi-hero {
    background: linear-gradient(135deg, rgba(255, 95, 156, 0.16), rgba(255, 157, 92, 0.1));
    border-color: rgba(255, 95, 156, 0.4);
}

.sigserv-container .sigserv-kpi-label {
    color: #9292b8;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    margin-bottom: 6px;
}

.sigserv-container .sigserv-kpi-value {
    font-size: 1.55rem;
    font-weight: 800;
    color: #ffffff;
}

.sigserv-container .sigserv-kpi-hero .sigserv-kpi-value {
    font-size: 2.7rem;
    line-height: 1.05;
    color: #ff5f9c;
}

.sigserv-container .sigserv-kpi-sub {
    margin-top: 4px;
    font-size: 0.68rem;
    color: #8a8ab0;
}

.sigserv-container .sigserv-panel {
    background: rgba(255, 255, 255, 0.035);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 22px;
}

.sigserv-container .sigserv-panel h3 {
    color: #ffffff;
    font-size: 1.15rem;
    margin: 0 0 6px 0;
}

.sigserv-container .sigserv-panel-hint {
    color: #a6a6c8;
    font-size: 0.86rem;
    line-height: 1.55;
    margin: 0 0 18px 0;
}

/* ---- signal grid (round 1) ---- */
.sigserv-container .sigserv-signal-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
    margin-bottom: 16px;
}

.sigserv-container .sigserv-signal {
    display: grid;
    grid-template-columns: auto 1fr;
    grid-template-areas: "chk name" "chk meta" "chk hyp";
    column-gap: 12px;
    row-gap: 3px;
    align-items: start;
    background: rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 14px 16px;
    cursor: pointer;
    transition: border-color 0.2s ease, background 0.2s ease;
}

.sigserv-container .sigserv-signal:hover { border-color: rgba(255, 178, 102, 0.45); }

.sigserv-container .sigserv-signal input[type="checkbox"] {
    grid-area: chk;
    width: 20px;
    height: 20px;
    margin-top: 3px;
    accent-color: #ff5f9c;
    cursor: pointer;
}

.sigserv-container .sigserv-signal-name {
    grid-area: name;
    font-weight: 700;
    font-size: 0.92rem;
    color: #ffffff;
}

.sigserv-container .sigserv-signal-meta {
    grid-area: meta;
    font-size: 0.74rem;
    color: #f6b86b;
    font-variant-numeric: tabular-nums;
}

.sigserv-container .sigserv-signal-hyp {
    grid-area: hyp;
    font-size: 0.78rem;
    color: #9d9dc4;
    line-height: 1.4;
}

.sigserv-container .sigserv-signal-summary,
.sigserv-container .sigserv-bet-fit,
.sigserv-container .sigserv-alloc-summary {
    background: rgba(255, 95, 156, 0.1);
    border-radius: 10px;
    padding: 12px 16px;
    font-size: 0.9rem;
    color: #c4c4e0;
}

.sigserv-container .sigserv-signal-summary strong,
.sigserv-container .sigserv-bet-fit strong,
.sigserv-container .sigserv-alloc-summary strong { color: #ffe2b0; }

.sigserv-container .sigserv-divider { margin: 0 10px; color: #5a5a80; }

/* ---- bet grid (round 2) ---- */
.sigserv-container .sigserv-bet-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.sigserv-container .sigserv-bet {
    display: block;
    background: rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 16px;
    cursor: pointer;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.sigserv-container .sigserv-bet:hover { border-color: rgba(255, 95, 156, 0.5); }

.sigserv-container .sigserv-bet input[type="radio"] {
    accent-color: #ff5f9c;
    width: 18px;
    height: 18px;
    vertical-align: middle;
    margin-right: 8px;
}

.sigserv-container .sigserv-bet-name {
    font-weight: 700;
    font-size: 0.95rem;
    color: #ffffff;
}

.sigserv-container .sigserv-bet-desc {
    display: block;
    margin-top: 6px;
    font-size: 0.8rem;
    color: #9d9dc4;
    line-height: 1.5;
}

/* ---- allocation grid (round 3) ---- */
.sigserv-container .sigserv-alloc-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.sigserv-container .sigserv-alloc-input {
    background: rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 14px 16px;
}

.sigserv-container .sigserv-alloc-input label {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.84rem;
    font-weight: 600;
    color: #c4c4e0;
    margin-bottom: 8px;
}

.sigserv-container .sigserv-alloc-icon { font-size: 1.1rem; }

.sigserv-container .sigserv-alloc-input input {
    width: 100%;
    padding: 9px 12px;
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 8px;
    background: rgba(0, 0, 0, 0.4);
    color: #ffffff;
    font-size: 1.05rem;
    font-weight: 700;
    text-align: right;
}

.sigserv-container .sigserv-alloc-input input:focus,
.sigserv-container .sigserv-recovery input:focus {
    outline: none;
    border-color: #ff5f9c;
    box-shadow: 0 0 0 3px rgba(255, 95, 156, 0.22);
}

/* ---- recovery (round 4) ---- */
.sigserv-container .sigserv-recovery {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
}

.sigserv-container .sigserv-recovery-block label {
    display: block;
    font-size: 0.82rem;
    font-weight: 600;
    color: #c4c4e0;
    margin-bottom: 8px;
}

.sigserv-container .sigserv-recovery select,
.sigserv-container .sigserv-recovery input {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 8px;
    background-color: #1a1230;
    color: #ffffff;
    font-size: 0.9rem;
    font-weight: 600;
}

.sigserv-container .sigserv-recovery select option {
    background-color: #1a1230;
    color: #ffffff;
}

.sigserv-container select:focus {
    outline: none;
    border-color: #ff5f9c;
    box-shadow: 0 0 0 3px rgba(255, 95, 156, 0.22);
}

/* ---- actions ---- */
.sigserv-container .sigserv-actions {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-bottom: 22px;
}

.sigserv-container .sigserv-actions .btn-primary {
    background: linear-gradient(120deg, #ff5f9c 0%, #ff9d5c 100%);
    border: none;
    color: #1a0a14;
    padding: 13px 38px;
    font-weight: 800;
    border-radius: 10px;
    font-size: 1rem;
    letter-spacing: 0.3px;
}

.sigserv-container .sigserv-actions .btn-primary:hover {
    box-shadow: 0 6px 24px rgba(255, 95, 156, 0.45);
    transform: translateY(-1px);
}

.sigserv-container .sigserv-actions .btn-outline-secondary {
    color: #9d9dc4;
    border-color: rgba(255, 255, 255, 0.18);
}

.sigserv-container .sigserv-actions .btn-outline-secondary:hover {
    color: #ffffff;
    border-color: rgba(255, 95, 156, 0.5);
}

/* ---- history ---- */
.sigserv-container .sigserv-history { margin-bottom: 22px; }

.sigserv-container .sigserv-history .table {
    background: rgba(255, 255, 255, 0.04);
    color: #d8d8ec;
    border-radius: 12px;
    overflow: hidden;
    margin: 0;
}

.sigserv-container .sigserv-history .table th {
    background: rgba(255, 95, 156, 0.16);
    color: #ffd28a;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    border: none;
    padding: 10px 12px;
}

.sigserv-container .sigserv-history .table td {
    border-color: rgba(255, 255, 255, 0.06);
    padding: 9px 12px;
    font-size: 0.86rem;
    font-variant-numeric: tabular-nums;
}

/* ---- charts ---- */
.sigserv-container .sigserv-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    margin-bottom: 14px;
}

.sigserv-container .sigserv-chart-wrapper {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 14px;
    padding: 18px;
    min-height: 300px;
}

@media (max-width: 992px) {
    .sigserv-container .sigserv-kpis { grid-template-columns: repeat(2, 1fr); }
    .sigserv-container .sigserv-kpi-hero { grid-column: 1 / -1; }
    .sigserv-container .sigserv-charts { grid-template-columns: 1fr; }
    .sigserv-container .sigserv-recovery { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
    .sigserv-container { padding: 14px; }
    .sigserv-container .sigserv-header { flex-direction: column; text-align: center; }
    .sigserv-container .sigserv-kpis { grid-template-columns: 1fr 1fr; }
    .sigserv-container .sigserv-signal-grid,
    .sigserv-container .sigserv-bet-grid,
    .sigserv-container .sigserv-alloc-grid { grid-template-columns: 1fr; }
    .sigserv-container .sigserv-kpi-hero .sigserv-kpi-value { font-size: 2.2rem; }
    .sigserv-container .sigserv-actions { flex-direction: column; align-items: stretch; }
}


/* FIX v1.1.0 - completion / board-debrief screen */
.sigserv-completion { padding: 8px 4px; text-align: center; }
.sigserv-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.sigserv-completion-verdict { font-size: 24px; font-weight: 700; color: #0f172a; margin-bottom: 14px; }
.sigserv-completion-score { display: inline-flex; align-items: baseline; gap: 8px; padding: 8px 16px; background: #f1f5f9; border-radius: 8px; margin-bottom: 18px; }
.sigserv-completion-score span { font-size: 13px; color: #64748b; }
.sigserv-completion-score strong { font-size: 20px; color: #0f172a; }
.sigserv-completion-insights-heading { font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: #64748b; margin-bottom: 8px; }
.sigserv-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 640px; text-align: left; }
.sigserv-completion-insights li { padding: 10px 14px; margin-bottom: 8px; background: #f8fafc; border-left: 3px solid #6366f1; border-radius: 4px; color: #1e293b; font-size: 14px; }

js:
(function () {
    'use strict';

    // ---- Static reference data (from concept Numbers Reference Card) ----
    var CAP = 6.0;                 // €6.0M hard board cap (capex + opex, full year)
    var CHURN_START = 4.1;         // post-shock monthly churn %
    var CHURN_FLOOR = 2.3;         // best achievable bend
    var CHURN_TARGET = 3.0;        // board target
    var SUBS = 3800000;            // subscribers
    var ARPU_MONTH = 10.99;        // € / month

    // Signal catalogue: affordance = genuine customer-value potential (0..1),
    // coverage is shown to tempt volume-chasers; device/geo are abundance traps.
    var SIGNALS = {
        sigSkip:    { key: 'skip',    cost: 0.55, affordance: 0.92, coverage: 0.88 },
        sigContext: { key: 'context', cost: 0.45, affordance: 0.86, coverage: 0.82 },
        sigSocial:  { key: 'social',  cost: 0.70, affordance: 0.74, coverage: 0.41 },
        sigSearch:  { key: 'search',  cost: 0.50, affordance: 0.83, coverage: 0.64 },
        sigPodcast: { key: 'podcast', cost: 0.40, affordance: 0.70, coverage: 0.58 },
        sigMood:    { key: 'mood',    cost: 0.60, affordance: 0.95, coverage: 0.36 },
        sigDevice:  { key: 'device',  cost: 0.30, affordance: 0.18, coverage: 0.99 },
        sigGeo:     { key: 'geo',     cost: 0.35, affordance: 0.22, coverage: 0.71 }
    };

    // Service bets: which signals they truly need, and their value/churn/adoption profile.
    var BETS = {
        mood:        { needs: ['skip', 'context', 'mood'], churnPower: 0.85, valueCeiling: 92, adoptionEase: 0.80, inimitability: 0.90 },
        marketplace: { needs: ['social'],                  churnPower: 0.55, valueCeiling: 80, adoptionEase: 0.45, inimitability: 0.70 },
        guarantee:   { needs: ['search', 'skip'],          churnPower: 0.95, valueCeiling: 88, adoptionEase: 0.72, inimitability: 0.78 },
        b2b:         { needs: ['podcast', 'context'],      churnPower: 0.25, valueCeiling: 70, adoptionEase: 0.60, inimitability: 0.65 }
    };

    function round1(v) { return Math.round(v * 10) / 10; }
    function round2(v) { return Math.round(v * 100) / 100; }
    function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
    function eurM(v) { return '€' + (Math.round(v * 100) / 100).toFixed(2) + 'M'; }

    class SignalToServiceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Signal to Service';
            this.version = '1.1.0';
            this.SIGNAL_IDS = Object.keys(SIGNALS);
            this.ROUNDS = [
                { round: 1, titleKey: 'r1_title', briefingKey: 'r1_briefing', badgeKey: 'r1_badge' },
                { round: 2, titleKey: 'r2_title', briefingKey: 'r2_briefing', badgeKey: 'r2_badge' },
                { round: 3, titleKey: 'r3_title', briefingKey: 'r3_briefing', badgeKey: 'r3_badge' },
                { round: 4, titleKey: 'r4_title', briefingKey: 'r4_briefing', badgeKey: 'r4_badge' }
            ];
        }

        // ---------------------------------------------------------------
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    capRemaining: CAP,
                    capSpent: 0,
                    activatedSignals: [],     // array of signal keys
                    signalCost: 0,
                    signalAffordance: 0,
                    chosenBet: null,
                    signalFit: 0,
                    dataQuality: 0,
                    serviceQuality: 0,
                    valueAdd: 0,
                    adoption: 0,
                    targetAdoption: 0,
                    churn: CHURN_START,
                    roi: null,
                    paybackMonths: null,
                    breakevenAdoption: null,
                    churnHistory: [CHURN_START],
                    valueHistory: [0],
                    adoptionHistory: [0]
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
            this._showPanel(state.currentPeriod || 1);
            this._wireLiveHelpers();
        }

        // ---- panel visibility per round ----
        _showPanel(period) {
            for (var i = 1; i <= 4; i++) {
                var el = document.getElementById('panelRound' + i);
                if (el) el.style.display = (i === period) ? 'block' : 'none';
            }
        }

        // ---- live, in-round helper readouts (no scoring) ----
        _wireLiveHelpers() {
            var self = this;
            this.SIGNAL_IDS.forEach(function (id) {
                var el = document.getElementById(id);
                if (el) el.addEventListener('change', function () { self._updateSignalSummary(); });
            });
            this._updateSignalSummary();

            var bets = document.querySelectorAll('input[name="serviceBet"]');
            for (var b = 0; b < bets.length; b++) {
                bets[b].addEventListener('change', function () { self._updateBetFit(); });
            }
            this._updateBetFit();

            ['dataEngInput', 'serviceBuildInput', 'gtmInput'].forEach(function (id) {
                var el = document.getElementById(id);
                if (el) el.addEventListener('input', function () { self._updateAllocSummary(); });
            });
            this._updateAllocSummary();
        }

        _readSelectedSignals() {
            var picked = [];
            var cost = 0;
            var afford = 0;
            for (var i = 0; i < this.SIGNAL_IDS.length; i++) {
                var id = this.SIGNAL_IDS[i];
                var el = document.getElementById(id);
                if (el && el.checked) {
                    var s = SIGNALS[id];
                    picked.push(s.key);
                    cost += s.cost;
                    afford += s.affordance;
                }
            }
            return { picked: picked, cost: round2(cost), affordance: round2(afford) };
        }

        _updateSignalSummary() {
            var r = this._readSelectedSignals();
            var c = document.getElementById('signalCostDisplay');
            var a = document.getElementById('signalAffordanceDisplay');
            if (c) c.textContent = eurM(r.cost);
            if (a) a.textContent = r.affordance.toFixed(2);
        }

        _readBet() {
            var bets = document.querySelectorAll('input[name="serviceBet"]');
            for (var b = 0; b < bets.length; b++) {
                if (bets[b].checked) return bets[b].value;
            }
            return 'mood';
        }

        _fitForBet(betKey, activeSignals) {
            var bet = BETS[betKey];
            if (!bet) return 0;
            var have = 0;
            for (var i = 0; i < bet.needs.length; i++) {
                if (activeSignals.indexOf(bet.needs[i]) !== -1) have++;
            }
            return bet.needs.length ? have / bet.needs.length : 0;
        }

        _updateBetFit() {
            var betKey = this._readBet();
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var active = ds.activatedSignals || this._readSelectedSignals().picked;
            var fit = this._fitForBet(betKey, active);
            var el = document.getElementById('betFitDisplay');
            if (el && window.mySimulation) {
                var label = Math.round(fit * 100) + '% — ';
                label += fit >= 0.999 ? window.mySimulation.t('fit_full')
                       : fit > 0 ? window.mySimulation.t('fit_partial')
                       : window.mySimulation.t('fit_none');
                el.textContent = label;
            }
        }

        _updateAllocSummary() {
            var de = parseFloat((document.getElementById('dataEngInput') || {}).value) || 0;
            var sb = parseFloat((document.getElementById('serviceBuildInput') || {}).value) || 0;
            var gtm = parseFloat((document.getElementById('gtmInput') || {}).value) || 0;
            var committed = round2(de + sb + gtm);
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var alreadySpent = ds.capSpent || 0;
            var totalC = document.getElementById('allocCommittedDisplay');
            var vsCap = document.getElementById('allocVsCapDisplay');
            if (totalC) totalC.textContent = eurM(committed);
            if (vsCap) {
                var grand = round2(alreadySpent + committed);
                vsCap.textContent = eurM(grand) + ' / ' + eurM(CAP);
            }
        }

        // ---- per-round briefing ----
        _updateBriefing(state) {
            var idx = clamp((state.currentPeriod || 1) - 1, 0, this.ROUNDS.length - 1);
            var rnd = this.ROUNDS[idx];
            var t = window.mySimulation ? function (k) { return window.mySimulation.t(k); } : function (k) { return k; };
            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var badgeEl = document.getElementById('briefingBadge');
            if (titleEl) titleEl.textContent = t(rnd.titleKey);
            if (textEl) textEl.innerHTML = t(rnd.briefingKey);
            if (badgeEl) badgeEl.textContent = t(rnd.badgeKey);
            this._showPanel(state.currentPeriod || 1);
        }

        // ---------------------------------------------------------------
        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod;
            var ds = window.mySimulation.state.domainState;

            if (period === 1) {
                var r = this._readSelectedSignals();
                if (r.picked.length < 2) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_no_signals'), 'warning');
                    return false;
                }
                if (r.cost > CAP) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_signal_overcap'), 'warning');
                    return false;
                }
                decisions.signals = r.picked;
                decisions.signalCost = r.cost;
                decisions.signalAffordance = r.affordance;
                return true;
            }

            if (period === 2) {
                var betKey = this._readBet();
                if (!BETS[betKey]) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_no_bet'), 'warning');
                    return false;
                }
                decisions.bet = betKey;
                decisions.signalFit = round2(this._fitForBet(betKey, ds.activatedSignals));
                return true;
            }

            if (period === 3) {
                var de = parseFloat((document.getElementById('dataEngInput') || {}).value);
                var sb = parseFloat((document.getElementById('serviceBuildInput') || {}).value);
                var gtm = parseFloat((document.getElementById('gtmInput') || {}).value);
                var tgt = parseFloat((document.getElementById('targetAdoptionInput') || {}).value);
                if (!Number.isFinite(de) || !Number.isFinite(sb) || !Number.isFinite(gtm) || !Number.isFinite(tgt)) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_alloc_nan'), 'warning');
                    return false;
                }
                if (de < 0 || sb < 0 || gtm < 0) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_alloc_neg'), 'warning');
                    return false;
                }
                var committed = round2(de + sb + gtm);
                var grand = round2(ds.capSpent + committed);
                if (grand > CAP + 0.001) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_overcap'), 'warning');
                    return false;
                }
                if (committed < 0.5) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_alloc_low'), 'warning');
                    return false;
                }
                decisions.dataEng = round2(de);
                decisions.serviceBuild = round2(sb);
                decisions.gtm = round2(gtm);
                decisions.targetAdoption = clamp(Math.round(tgt), 0, 100);
                return true;
            }

            // period 4
            var move = (document.getElementById('recoveryMoveSelect') || {}).value || 'hold';
            var framing = (document.getElementById('framingSelect') || {}).value || 'job';
            var reserve = parseFloat((document.getElementById('reserveInput') || {}).value);
            if (!Number.isFinite(reserve) || reserve < 0) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_reserve_nan'), 'warning');
                return false;
            }
            if (round2(ds.capSpent + reserve) > CAP + 0.001) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_reserve_overcap'), 'warning');
                return false;
            }
            decisions.recoveryMove = move;
            decisions.framing = framing;
            decisions.reserve = round2(reserve);
            return true;
        }

        // ---------------------------------------------------------------
        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var res = { period: period };

            if (period === 1) {
                ds.activatedSignals = d.signals.slice();
                ds.signalCost = d.signalCost;
                ds.signalAffordance = d.signalAffordance;
                ds.capSpent = round2(ds.capSpent + d.signalCost);
                ds.capRemaining = round2(CAP - ds.capSpent);
                // affordance density: reward value per euro, penalise abundance dumping
                var density = ds.signalCost > 0 ? ds.signalAffordance / ds.signalCost : 0;
                res.signalsCount = d.signals.length;
                res.signalCost = d.signalCost;
                res.signalAffordance = ds.signalAffordance;
                res.affordanceDensity = round2(density);
                ds.valueHistory.push(0);
                ds.adoptionHistory.push(0);
                ds.churnHistory.push(CHURN_START);
            }

            else if (period === 2) {
                ds.chosenBet = d.bet;
                ds.signalFit = d.signalFit;
                var bet = BETS[d.bet];
                // value potential locked by fit and affordance of activated signals
                var potential = bet.valueCeiling * (0.35 + 0.65 * ds.signalFit) * (0.5 + 0.5 * Math.min(1, ds.signalAffordance / 2.6));
                ds.valuePotential = round1(potential);
                res.bet = d.bet;
                res.signalFit = d.signalFit;
                res.valuePotential = ds.valuePotential;
                res.inimitability = bet.inimitability;
                ds.valueHistory.push(0);
                ds.adoptionHistory.push(0);
                ds.churnHistory.push(CHURN_START);
            }

            else if (period === 3) {
                ds.dataEng = d.dataEng;
                ds.serviceBuild = d.serviceBuild;
                ds.gtm = d.gtm;
                ds.targetAdoption = d.targetAdoption;
                ds.capSpent = round2(ds.capSpent + d.dataEng + d.serviceBuild + d.gtm);
                ds.capRemaining = round2(CAP - ds.capSpent);

                this._computeService(ds, 1.0, ds.gtm, 'job');

                res.dataQuality = ds.dataQuality;
                res.serviceQuality = ds.serviceQuality;
                res.valueAdd = ds.valueAdd;
                res.adoption = ds.adoption;
                res.targetAdoption = ds.targetAdoption;
                res.churn = ds.churn;
                res.roi = ds.roi;
                res.paybackMonths = ds.paybackMonths;
                res.breakevenAdoption = ds.breakevenAdoption;
                res.capRemaining = ds.capRemaining;
                ds.valueHistory.push(ds.valueAdd);
                ds.adoptionHistory.push(ds.adoption);
                ds.churnHistory.push(ds.churn);
            }

            else { // period 4 — shock + recovery
                // Early adoption lands ~38% below plan; the recovery move can claw it back.
                var shock = 0.62;
                var extraGtm = 0;
                if (d.recoveryMove === 'double') {
                    // Push reserve into go-to-market AND recover much of the shock through it.
                    extraGtm = d.reserve;
                    shock = 0.62 + 0.30 * Math.min(1, d.reserve / 0.5);
                } else if (d.recoveryMove === 'reallocate') {
                    // Fix data quality; modest shock recovery from a steadier launch.
                    ds.dataEng = round2(ds.dataEng + d.reserve);
                    shock = 0.62 + 0.14 * Math.min(1, d.reserve / 0.5);
                }
                // 'hold' protects the reserve but rides the full shock.
                if (d.recoveryMove !== 'hold') {
                    ds.capSpent = round2(ds.capSpent + d.reserve);
                    ds.capRemaining = round2(CAP - ds.capSpent);
                }
                shock = clamp(shock, 0, 1);
                var effectiveGtm = ds.gtm + extraGtm;
                this._computeService(ds, shock, effectiveGtm, d.framing);

                res.recoveryMove = d.recoveryMove;
                res.framing = d.framing;
                res.dataQuality = ds.dataQuality;
                res.serviceQuality = ds.serviceQuality;
                res.valueAdd = ds.valueAdd;
                res.adoption = ds.adoption;
                res.churn = ds.churn;
                res.roi = ds.roi;
                res.paybackMonths = ds.paybackMonths;
                res.breakevenAdoption = ds.breakevenAdoption;
                res.capRemaining = ds.capRemaining;
                res.churnArrested = round1(CHURN_START - ds.churn);
                ds.valueHistory.push(ds.valueAdd);
                ds.adoptionHistory.push(ds.adoption);
                ds.churnHistory.push(ds.churn);
            }

            // FIX v1.1.0 - persist score so the Express reporting layer reads it
            // (express_resolveDomainScore -> performance.overallScore / top-level score).
            // Same formula as getPerformanceSummary via the shared _computeScore helper.
            ds.score = this._computeScore(ds);
            ds.performance = { overallScore: ds.score, grade: this._grade(ds.score) };

            var self = this;
            setTimeout(function () { self._updateBriefing(window.mySimulation.state); }, 500);
            return res;
        }

        // Core data-to-value chain. shockFactor scales realised adoption.
        _computeService(ds, shockFactor, gtm, framing) {
            var bet = BETS[ds.chosenBet] || BETS.mood;

            // Data quality: signal affordance + engineering, diminishing past ~2.4M
            var deEff = ds.dataEng <= 2.4 ? ds.dataEng / 2.4 : 1 + Math.log(ds.dataEng / 2.4) * 0.18;
            var dataQuality = clamp(0.30 + 0.45 * Math.min(1, ds.signalAffordance / 2.6) * ds.signalFit + 0.40 * Math.min(1.2, deEff), 0, 1);

            // Service build, but capped by data quality (data starves service)
            var buildEff = ds.serviceBuild <= 2.0 ? ds.serviceBuild / 2.0 : 1 + Math.log(ds.serviceBuild / 2.0) * 0.15;
            var serviceQuality = clamp(Math.min(1.05, 0.25 + 0.75 * Math.min(1.2, buildEff)) * (0.55 + 0.45 * dataQuality), 0, 1);

            // Framing: job-to-be-done addresses why subscribers churn; feature-list does not.
            var frameMult = framing === 'job' ? 1.0 : 0.78;

            // Value-add (0..valueCeiling): service quality x signal affordance x framing
            var valueAdd = bet.valueCeiling * serviceQuality * (0.55 + 0.45 * Math.min(1, ds.signalAffordance / 2.6)) * frameMult;
            valueAdd = clamp(valueAdd, 0, bet.valueCeiling);

            // Adoption: needs go-to-market AND a service worth adopting.
            var gtmEff = gtm <= 1.6 ? gtm / 1.6 : 1 + Math.log(gtm / 1.6) * 0.20;
            var adoptionRaw = 38 * Math.min(1.25, gtmEff) * bet.adoptionEase * (0.4 + 0.6 * serviceQuality) * (0.6 + 0.4 * frameMult);
            var adoption = clamp(adoptionRaw * shockFactor, 0, 60);

            // Churn bend: power of the bet x adoption x value-in-use.
            var bend = (CHURN_START - CHURN_FLOOR) * bet.churnPower * (adoption / 30) * (valueAdd / bet.valueCeiling) * frameMult;
            var churn = clamp(CHURN_START - bend, CHURN_FLOOR, CHURN_START);

            // Economics
            var totalSpend = ds.capSpent; // € millions committed so far
            // retained subs vs no-action baseline -> annual saved revenue (€M)
            var savedChurnPP = CHURN_START - churn;            // percentage points / month
            var savedSubsMonth = SUBS * (savedChurnPP / 100);   // subscribers saved per month
            var savedRevAnnual = (savedSubsMonth * ARPU_MONTH * 12) / 1e6; // €M / yr
            var serviceUplift = (SUBS * (adoption / 100) * ARPU_MONTH * 0.10 * 12) / 1e6; // 10% ARPU lift on adopters, €M/yr
            var annualReturn = savedRevAnnual + serviceUplift;

            var roi = totalSpend > 0 ? ((annualReturn - totalSpend) / totalSpend) * 100 : 0;
            var paybackMonths = annualReturn > 0 ? (totalSpend / annualReturn) * 12 : null;
            var breakeven = bet.churnPower > 0 ? clamp(totalSpend / Math.max(0.01, annualReturn / Math.max(1, adoption)), 0, 100) : null;

            ds.dataQuality = round2(dataQuality);
            ds.serviceQuality = round2(serviceQuality);
            ds.valueAdd = round1(valueAdd);
            ds.adoption = round1(adoption);
            ds.churn = round2(churn);
            ds.roi = Math.round(roi);
            ds.paybackMonths = paybackMonths === null ? null : round1(paybackMonths);
            ds.breakevenAdoption = breakeven === null ? null : round1(breakeven);
            ds.annualReturn = round2(annualReturn);
        }

