            });
            uiManager.bind('churnDisplay', 'domainState.churn', function (v) {
                return (typeof v === 'number' ? v.toFixed(2) : CHURN_START.toFixed(2)) + '%';
            });
            uiManager.bind('valueAddDisplay', 'domainState.valueAdd', function (v) {
                return Math.round(v || 0);
            });
            uiManager.bind('adoptionDisplay', 'domainState.adoption', function (v) {
                return (Math.round((v || 0) * 10) / 10) + '%';
            });
            uiManager.bind('roiDisplay', 'domainState.roi', function (v) {
                if (v === null || v === undefined) return '—';
                return (v > 0 ? '+' : '') + v + '%';
            });
            uiManager.bind('paybackDisplay', 'domainState.paybackMonths', function (v) {
                if (v === null || v === undefined) return '—';
                return v + window.mySimulation.t('months_suffix');
            });
        }

